const payload = $input.first().json;
const ticker = payload.ticker || 'BTC/USDT';
const price = payload.currentPrice || 64250;
const rsi = payload.rsi || 56.4;
const macdHist = payload.macdHist || 12.8;
const ema50 = payload.ema50 || 63800;
const ema200 = payload.ema200 || 61500;
const atr = payload.atr || 850;

const isBullish = rsi > 45 && rsi < 70 && macdHist > 0 && price > ema50 && ema50 > ema200;
const isBearish = rsi < 45 && macdHist < 0 && price < ema50;
const action = isBullish ? 'BUY' : isBearish ? 'SELL' : 'HOLD';

return {
  json: {
    ticker,
    price,
    action,
    rsi,
    macdHist,
    ema50,
    ema200,
    atr,
    stopLoss: isBullish ? price - (atr * 1.5) : price + (atr * 1.5),
    takeProfit1: isBullish ? price + (atr * 2.2) : price - (atr * 2.2),
    takeProfit2: isBullish ? price + (atr * 3.8) : price - (atr * 3.8),
    confidence: isBullish ? 85 : isBearish ? 80 : 50
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'technical-analyst',
    botName: 'Multi-Timeframe Technical Analysis Agent',
    technicalSummary: text,
    status: 'ACTIVE_SETUP',
    timestamp: new Date().toISOString()
  }
};
